logger.message:
#[%dw 2.0
output application/json
---
{
  "step": "after retrieve products",
  "data": {
    "business": {
      "productId": vars.productId, 
      "qty": vars.qty    
    },
    "technical": {
      "timestamp": now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"},
      "payload": payload
    }
  }
}]

ee:message.ee:set-payload:
%dw 2.0
output application/csv 
---

(payload map (item) -> 

		if (item.id == vars.productId) 
   		item update {
            case .stock -> (item.stock default 0) - vars.qty
        }
    	else item
)
	filter (item) -> (item.stock as Number > 0)

