ee:message.ee:set-payload:
%dw 2.0 output application/json
var payloadjson = if (payload is Binary) read(payload, "application/json") else payload --- payloadjson map(item,index)-> { id: item.id as Number, name: item.name, category: item.category, price: item.price as Number, stock: item.stock as Number
}

